    .reg .b32    %r<48>;
    .reg .b64    %rd<32>;
    .reg .f32    %f<16>;
    .reg .b32    %rN, %rBx, %rBy, %rTx, %rTy, %rBDx, %rBDy, %ri, %rj, %rk, %rRowA;
