    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %rN,  [N_param];
    // Compute thread coordinates (j = x, i = y)
    mov.u32 %rBx, %ctaid.x;
    mov.u32 %rBy, %ctaid.y;
    mov.u32 %rTx, %tid.x;
    mov.u32 %rTy, %tid.y;
    mov.u32 %rBDx, %ntid.x;
    mov.u32 %rBDy, %ntid.y;
    mul.lo.u32 %r0, %rBx, %rBDx;    // r0 = blockIdx.x * blockDim.x
    add.u32    %rj, %r0,  %rTx;     // j index
    mul.lo.u32 %r1, %rBy, %rBDy;    // r1 = blockIdx.y * blockDim.y
    add.u32    %ri, %r1,  %rTy;     // i index
    // Bounds check: if i >= N or j >= N, return
    setp.ge.u32 %p0, %ri, %rN;
    setp.ge.u32 %p1, %rj, %rN;
    or.pred     %p2, %p0, %p1;
    @%p2 bra DONE;
    // If i > j, write zero and return
    setp.gt.u32 %p3, %ri, %rj;
    @!%p3 bra COMPUTE; // if not (i>j), go compute
    // STORE ZERO PATH
    // idxC = i*N + j
    mul.lo.u32   %r2, %ri, %rN;
    add.u32      %r3, %r2, %rj;
    mul.wide.u32 %rd10, %r3, 4;
    add.s64      %rd11, %rd3, %rd10;
    mov.f32      %f0, 0f00000000;
    st.global.f32 [%rd11], %f0;
    bra DONE;
