    // sum over k from i to j (inclusive) with A vectorized loads (v2) and unrolling by 2
    mov.f32 %f1, 0f00000000;   // accumulator
    mov.u32 %rk, %ri;          // k = i
    // Precompute row base for A: i * N
    mul.lo.u32 %rRowA, %ri, %rN;
