    mul.lo.u32   %r6, %rk, %rN;        // k * N
    add.u32      %r7, %r6, %rj;        // k*N + j
    mul.wide.u32 %rd6, %r7, 4;
    add.s64      %rd7, %rd2, %rd6;     // B ptr + offset
    ld.global.f32 %f3, [%rd7];
    // Accumulate
    fma.rn.f32 %f1, %f2, %f3, %f1;
    // k++ and loop
    add.u32 %rk, %rk, 1;
    bra ALIGN_PRE;
AFTER_ALIGN:
VEC_LOOP:
    // Guard: if rk > rj, end compute to store result
    setp.gt.u32 %p4, %rk, %rj;
    @%p4 bra END_LOOP;
    // Vectorized loop: process two k's per iteration when (rk + 1) <= j
