    // Load A[i, k]
    add.u32      %r5, %rRowA, %rk;    // i*N + k
    mul.wide.u32 %rd4, %r5, 4;
    add.s64      %rd5, %rd1, %rd4;
    ld.global.f32 %f2, [%rd5];
    // Load B[k, j]
    mul.lo.u32   %r6, %rk, %rN;       // k * N
    add.u32      %r7, %r6, %rj;       // k*N + j
    mul.wide.u32 %rd6, %r7, 4;
    add.s64      %rd7, %rd2, %rd6;
    ld.global.f32 %f3, [%rd7];
